@id("close-main-with-human-approval-via-authority")
permit (principal, action == Drupe::Action::"close_workorder", resource)
when { context.input.site_id == "MAIN" }
when temporal {
  formerly within 1h Drupe::Action::"authority_get_approval"::response{
    eventResource: resource,
    input.wonum: context.input.wonum,
    input.site_id: context.input.site_id,
    output.decision: "GRANTED",
    output.approver_kind: "HUMAN"
  }
};

@id("close-main-with-human-approval-via-get-workorder")
permit (principal, action == Drupe::Action::"close_workorder", resource)
when { context.input.site_id == "MAIN" }
when temporal {
  formerly within 1h Drupe::Action::"get_workorder"::response{
    eventResource: resource,
    input.wonum: context.input.wonum,
    input.site_id: context.input.site_id,
    output.approval_outcome: "GRANTED",
    output.approver_type: "HUMAN"
  }
};

// Read-only lookups (must be permitted so their responses are recorded).
@id("allow-read-authority-get-approval")
permit (principal, action == Drupe::Action::"authority_get_approval", resource);

@id("allow-read-get-workorder")
permit (principal, action == Drupe::Action::"get_workorder", resource);

@id("allow-read-get-workorder-tasks")
